import { Children } from 'react';
import './Card.css';

function Card(){
    return<>
    <div className="card">
hye i am card
    </div>
    </>
}

function CardWithImage({Children,src}){
    return<><Card>
    <div className='img'>
        <img src={src}/>
       
    </div>
     <div>{Children}</div>
    </Card>
    </>
}

function CardWithTitle({title, Children}){
    return<><Card>
        <h3>{title}</h3>
    <div className='title'>
        <span>{Children}</span>
    </div>
    </Card>
    </>
}

export {
    Card,
    CardWithTitle,
    CardWithImage
}
